// Create a reference to the Native API module
const IRISNative = require('@intersystems/intersystems-iris-native')

// Open a connection to the server and create an Iris object
const connectionInfo = {
  host: '127.0.0.1',
  port: 1972,
  ns: 'USER',
  user: 'username',
  pwd: 'password'
}

const conn = IRISNative.createConnection(connectionInfo)
const native = conn.createIris()

// create global array

// if heros exists, destroy it first
native.kill('heros')

native.set(1919, 'heros', 'dogs', 'Balto')
native.set(1923, 'heros', 'dogs', 'Hachiko')
native.set(1940, 'heros', 'dogs', 'Lassie')
native.set(1954, 'heros', 'dogs', 'Lassie', 'Timmy')
native.set(1906, 'heros', 'dogs', 'Whitefang')
native.set(1996, 'heros', 'sheep', 'Dolly')

// Create a reverse iterator for child nodes of heros('dogs')
let iterDogs = native.iterator('heros', 'dogs').reversed().startFrom('V')
let output = '\nDog birth years: '
let key, value
for ([key, value] of iterDogs) {
  output += key + ':' + value + '  '
}
console.log(output)
// Should print:   Dog birth years: Lassie:1940  Hachiko:1923  Balto:1919

// Get a list of child subscripts under node heros('dogs')
iterDogs = native.iterator('heros', 'dogs').keys()
output = "\nSubscripts under node heros('dogs'): "

let iter = iterDogs.next()
while (!iter.done) {
  output += iter.value + ' '
  iter = iterDogs.next()
}
console.log(output)
// Should print:   Subscripts under node heros('dogs'): Balto Hachiko Lassie Whitefang

conn.close()
